// The `TryFrom<HttpInputValue>` impl generated by `MyHttpStringEnum` returns
// `Result<Self, Self::Error>`, and `Self::Error` is ambiguous with the `Error` variant below.
// In a type position it can only be the associated type, so the code is correct - remove the
// allow once my-http-utils names the error type directly.
#![allow(ambiguous_associated_items)]

use my_http_utils::macros::MyHttpStringEnum;

/// Ids match `LogLevelGrpcModel` of MyLogger.proto. `MyHttpStringEnum` owns the serde impls too,
/// so the `value` string is what goes over the wire.
#[derive(MyHttpStringEnum, Debug, Clone, PartialEq, Eq)]
pub enum LogApiLevel {
    #[http_enum_case(id = "0", value = "Info", description = "Info")]
    Info,
    #[http_enum_case(id = "1", value = "Warning", description = "Warning")]
    Warning,
    #[http_enum_case(id = "2", value = "Error", description = "Error")]
    Error,
    #[http_enum_case(id = "3", value = "Fatal", description = "Fatal error")]
    FatalError,
    #[http_enum_case(id = "4", value = "Debug", description = "Debug")]
    Debug,
}
